/*getBdgtSelect*/
SELECT A.AUFNR, A.BGACT, MAX(A.ACTTX) AS ACTTX, MAX(A.MPAMT) + MAX(A.GR_AMT) AS MPAMT, MAX(A.PLAN_AMT_FLAG) AS PLAN_AMT_FLAG FROM ( SELECT A.AUFNR, A.BGACT, A.ACTTX, (NVL(B.MPAMT,0) - NVL(C.TEMP_AMT+C.RESULT_AMT,0)) AS MPAMT, CASE WHEN B.MPAMT - NVL(C.TEMP_AMT+C.RESULT_AMT,0) + NVL( F_COWAY_BUYER_BUDGET_MPAMT2 (C.BUYER , C.DEPT , C.ACCOUNT_TYPE,C.TERM) ,0 ) > 1 THEN 'Y' ELSE 'N' END AS PLAN_AMT_FLAG, (SELECT NVL(SUM(GR.ITEM_AMT),0) FROM COWAY_BUDGET_ACTUAL BD, ICOMPODT PO, ICOMGRDT GR WHERE BD.BUYER = #{st_buyer} AND BD.BUYER = C.BUYER AND BD.BUDGET_DEPT = C.DEPT AND BD.ACCOUNT_TYPE = C.ACCOUNT_TYPE AND BD.ADD_DATE BETWEEN C.FROM_DATE AND C.TO_DATE AND PO.BUYER = BD.BUYER AND PO.PR_NO = BD.PR_NO AND PO.PR_SEQ = BD.PR_SEQ AND GR.BUYER = PO.BUYER AND GR.PO_NO = PO.PO_NO AND GR.PO_SEQ = PO.PO_SEQ AND TRIM(GR.LEGACY_PO_NO) IS NULL AND TRIM(GR.LEGACY_GR_NO) IS NOT NULL AND GR.STATUS IN ('C','R') ) AS GR_AMT FROM COWAY_MAPPING_ET_BG_MASTER A, COWAY_RESTS_ET_ORDER B, ICOMBDGT C WHERE 1 = 1 AND B.KOKRS = '2000' AND A.KOKRS = B.KOKRS AND A.BGACT = B.BGACT AND A.AUFNR = B.AUFNR AND C.BUYER= #{st_buyer} AND B.AUFNR=C.DEPT AND B.BGACT=C.ACCOUNT_TYPE AND C.TERM_TYPE='M' AND B.GJAHR||LPAD(B.MONAT,2,'0')=C.TERM AND TO_CHAR (SYSDATE, 'YYYYMMDD') BETWEEN C.FROM_DATE AND C.TO_DATE AND B.AUFNR = #{st_userDept}
AND A.BGACT LIKE '%'||#{account_cd}||'%'
AND A.ACTTX LIKE '%'||#{account_nm}||'%'
)A GROUP BY AUFNR, BGACT

/*getBuyerAdminBudgetListSql*/
SELECT A. AUFNR , (SELECT D . LTEXT FROM COWAY_BUDGET_ORG_ET_TREE D WHERE D. BGORG =A.AUFNR AND ROWNUM= 1 ) AUFNR_NM ,A.BGACT ,MAX(A.ACTTX ) ACTTX ,MAX(A.REST_AMT ) REST_AMT ,MAX(A.MPAMT ) MPAMT ,MAX(A.TERM) TERM FROM( SELECT A. AUFNR ,A.BGACT , A.ACTTX , (NVL(B . MPAMT, 0 ) + NVL( F_COWAY_BUYER_BUDGET_MPAMT2 ('KRCOWA0001' , C .DEPT , C .ACCOUNT_TYPE,C.TERM) ,0 ) - (NVL(C .TEMP_AMT,0) + NVL(C. RESULT_AMT ,0 ))) REST_AMT
, NVL(C .TEMP_AMT,0) + NVL(C. RESULT_AMT ,0 ) MPAMT , CASE WHEN B. MPAMT - NVL(C .TEMP_AMT + C. RESULT_AMT ,0 ) > 1 THEN 'Y' ELSE 'N' END PLAN_AMT_FLAG , B . GJAHR , B .MONAT , C .TERM AS TERM FROM COWAY_MAPPING_ET_BG_MASTER A, COWAY_RESTS_ET_ORDER B , ICOMBDGT C WHERE 1 = 1 AND B . KOKRS = '2000' AND A. KOKRS = B. KOKRS AND A. BGACT = B. BGACT AND A. AUFNR = B. AUFNR AND B . AUFNR= C .DEPT AND B . BGACT= C .ACCOUNT_TYPE AND C. TERM_TYPE ='M' AND B . GJAHR||LPAD( B .MONAT , 2, '0' )=C .TERM AND C. BUYER = #{st_buyer} AND C.TERM = #{st_from_year}||#{st_from_month}
AND C.DEPT =#{st_account_type}
)A GROUP BY AUFNR, BGACT

