SELECT (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.TYPE = 'Z014' AND C.COMPANY_CODE = X.BUYER AND C.CODE = X.ACCOUNT_TYPE ) ACCOUNT_TYPE_TEXT, -- 0 Z.MPAMT, -- 1 Y.RESULT_AMT-NVL(F_COWAY_BUYER_BUDGET_MPAMT(X.BUYER, X.BUDGET_DEPT, X.ACCOUNT_TYPE) ,0) RESULT_AMT, -- 2 Y.TEMP_AMT, -- 3 X.TOT_AMT, -- 4 DECODE(SIGN(Z.MPAMT - (Y.RESULT_AMT-NVL(F_COWAY_BUYER_BUDGET_MPAMT(X.BUYER, X.BUDGET_DEPT, X.ACCOUNT_TYPE) ,0) + Y.TEMP_AMT + X.TOT_AMT)),NULL,'예산미편성',-1 ,'예산초과','예산적용') BUYER_CHECK, -- 5 X.BUDGET_DEPT , -- 6 X.ACCOUNT_TYPE, -- 7 (SELECT TEXT1 FROM ICOMCOD2 A WHERE A.COMPANY_CODE = X.BUYER AND A.CODE = X.BUDGET_DEPT AND A.TYPE = 'C001' ) AS BUDGET_DEPT_NAME -- 8 FROM (SELECT MAX(A.BUYER) BUYER, A.BUDGET_DEPT , A.ACCOUNT_TYPE, SUM((DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)))) TOT_AMT FROM ICOMCART A, ICOMBYIT B, ICOMCQDT C WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.BUYER = #{buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{userid}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ||A.SEQ IN
#{item}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ IN
#{item}
AND A.USE_FLAG = 'C' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG = 'N' AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND B.ACCOUNT_TYPE = 'M' GROUP BY A.BUDGET_DEPT , A.ACCOUNT_TYPE ) X , ICOMBDGT Y , COWAY_RESTS_ET_ORDER Z WHERE X.BUYER = Y.BUYER AND X.BUDGET_DEPT = Y.DEPT AND X.ACCOUNT_TYPE = Y.ACCOUNT_TYPE AND X.BUDGET_DEPT = Z.AUFNR AND X.ACCOUNT_TYPE = Z.BGACT AND Z.KOKRS = '2000' AND Z.GJAHR =SUBSTR(Y.TERM,0,4) AND LPAD(Z.MONAT,2,'0') = SUBSTR(Y.TERM,5,2) AND TO_CHAR (SYSDATE, 'YYYYMMDD') BETWEEN Y.FROM_DATE AND Y.TO_DATE
